<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useAuthStore} from '../../stores/auth'
import type {PredictionRecord} from '../../api/predictions'
import {explanation,generateExplanation,type ExplanationView} from '../../api/explanations'
const props=defineProps<{record:PredictionRecord}>(),auth=useAuthStore()
const view=ref<ExplanationView|null>(null),busy=ref(false),generating=ref(false),error=ref(''),pendingOperation=ref('')
let generation=0
const running=computed(()=>view.value?.latestAttempt?.state==='RUNNING'&&!view.value.latestAttempt.expired)
const labels:Record<string,string>={overview:'结果概览',readout:'如何理解',risk:'风险与限制'}
function failureMessage(code:string|null){return ({AI_SERVICE_FROZEN:'AI解释服务已暂停，需管理员检查云端服务状态。原预测和已有解释仍可查看。',AI_AUTH_DENIED:'云端拒绝了AI解释请求，需管理员检查调用权限。原预测和已有解释仍可查看。',AI_OUTPUT_INVALID:'返回的解释未通过数据核对，可重新生成。原预测和已有解释保留。'} as Record<string,string>)[code||'']||'上次解释未完成，原预测和已有解释保留。'}
async function load(){if(!auth.profile||props.record.state!=='SUCCEEDED')return;const g=generation;busy.value=true;error.value='';try{const value=await explanation(props.record.predictionId);if(g!==generation)return;view.value=value;if(value.latestAttempt?.operationId===pendingOperation.value&&(value.latestAttempt.state!=='RUNNING'||value.latestAttempt.expired))pendingOperation.value='';}catch{if(g===generation)error.value='查询失败，已有解释保留，请稍后刷新。'}finally{if(g===generation)busy.value=false}}
async function generate(){if(!auth.profile||generating.value||running.value||!view.value?.configured)return;const g=generation;generating.value=true;error.value='';const operation=pendingOperation.value||crypto.randomUUID();pendingOperation.value=operation;try{const result=await generateExplanation(props.record.predictionId,operation);if(g!==generation)return;pendingOperation.value='';view.value={...view.value!,latestAttempt:result};if(result.state==='FAILED')error.value='解释未通过或服务暂时不可用，原预测保留。';await load()}catch{if(g===generation)error.value='本次请求状态未确认，请先刷新；再次提交会复用同一请求编号。'}finally{if(g===generation)generating.value=false}}
watch(()=>[auth.profile?.userId,props.record.predictionId,props.record.state],()=>{generation++;view.value=null;busy.value=false;generating.value=false;error.value='';pendingOperation.value='';void load()},{immediate:true,flush:'sync'})
onBeforeUnmount(()=>generation++)
</script>
<template><section class="explanation" aria-label="AI预测解释"><div class="heading"><h3>AI预测解释</h3><div class="actions"><button data-refresh :disabled="busy||generating||!auth.profile" @click="load()">{{busy?'正在查询…':'刷新解释记录'}}</button><button v-if="view?.configured" data-generate :disabled="busy||generating||running" @click="generate()">{{generating?'正在生成…':pendingOperation?'重试本次请求':view.latest?'重新生成解释':'生成解释'}}</button></div></div><p class="hint">结合本次预测和已保存的验证记录说明结果，仅供辅助参考。点击生成才调用AI，可能产生费用；打开页面和刷新记录不会自动生成。</p><p v-if="error" role="alert">{{error}}</p><p v-if="view?.stale" role="status">依据已更新，以下保留上次解释；可重新生成以使用当前验证记录。</p><p v-if="generating||running" role="status">解释正在生成，请稍后刷新记录。</p><p v-else-if="view?.latestAttempt?.state==='FAILED'" role="status">{{failureMessage(view.latestAttempt.errorCode)}}</p><p v-if="view&&!view.configured">AI解释尚未配置，预测曲线和验证记录仍可查看。</p><p v-if="!auth.profile">请登录后查看本人解释。</p><template v-if="view?.latest"><p v-if="view.latest.needsReview" role="status">旧版解释待重新核验，暂不展示正文。预测数值与解释依据仍保留，服务恢复后可重新生成。</p><template v-else><article v-for="p in view.latest.paragraphs" :key="p.kind"><h4>{{labels[p.kind]||p.kind}}</h4><p>{{p.text}}</p><small>引用依据：{{p.refs.join('、')}}</small></article></template><details><summary>查看解释依据</summary><dl><dt>解释编号</dt><dd>{{view.latest.explanationId}}</dd><dt>生成时间</dt><dd>{{view.latest.createdAt}}</dd><dt>文本模型</dt><dd>{{view.latest.context.providerModel}}</dd><dt>提示词版本</dt><dd>{{view.latest.context.promptVersion}}</dd><template v-for="(value,key) in view.latest.context.facts" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl></details></template></section></template>
<style scoped>.explanation{border-top:1px solid var(--border);margin-top:24px;padding-top:18px}.heading,.actions{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}h3{font-size:20px;margin:0}h4{font-size:16px;margin:0 0 8px}article{margin:16px 0;padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:10px}p{line-height:1.7;overflow-wrap:anywhere}small,.hint,dd{color:var(--muted)}button{font:inherit;min-height:44px;padding:10px 14px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--ink);cursor:pointer}button:disabled{opacity:.6;cursor:default}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}summary{cursor:pointer;min-height:44px}dd{margin:4px 0 12px;overflow-wrap:anywhere}dt{font-weight:600}</style>
